css:
body {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 11px;
    color: #000;
}

.company-header {
    margin-bottom: 5px;
}

.company-name {
    font-size: 16px;
    font-weight: bold;
    text-transform: uppercase;
    text-align: left;
    margin-bottom: 5px;
}

.company-address {
    margin-top: 5px;
    line-height: 1.5;
}

.party-section {
    width: 100%;
    margin-top: 5px;
    margin-bottom: 5px;
}

.party-left {
    float: left;
    width: 70%;
}

.party-right {
    float: right;
    width: 25%;
    text-align: right;
}

.clearfix {
    clear: both;
}

.separator {
    border-top: 1px solid #000;
    margin: 5px 0;
}
.details-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0px !important;
    margin-bottom: 0px !important;
}

.details-table td {
    padding: 0px !important;
    line-height: 1.1 !important;
    vertical-align: top;
    border: none !important;
    color:#222;
}

.details-table tr {
    height: 16px !important;
}

.label {
    width: 170px;
    font-weight: bold;
    white-space: nowrap;
}

.value {
    padding-left: 0;
}

.label {
    width: 180px;
    font-weight: bold;
    white-space: nowrap;
    border: none !important;
    padding-right: 10px;
}

.section-title {
    font-weight: bold;
    text-decoration: underline;
    margin-top: 0px !important;
    margin-bottom: 2px !important;
    padding: 0px !important;
}

.adjustment-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
    margin-top: 10px;
    font-size: 13px;
}

.adjustment-table th,
.adjustment-table td {
    border: 1px solid #000 !important;
    padding: 1px 3px !important;
    line-height: 1.0 !important;
}

.adjustment-table tr {
    border: 1px solid #000 !important;
}

.adjustment-table tbody tr {
    border-bottom: 1px solid #000 !important;
}

.adjustment-table th {
    text-align: center;
    font-weight: bold;
    background: #f5f5f5;
}

.adjustment-table td {
    vertical-align: middle;
}
.company-header,
.party-section,
.details-table,
.section-title {
    font-size: 13px;
}
.adjustment-table table,
.adjustment-table tr,
.adjustment-table td,
.adjustment-table th {
    border-collapse: collapse !important;
}
.print-format {
    padding: 12px !important;
    margin: 0 !important;
}

p {
    margin: 0;
}

table {
    margin-bottom: 0;
}
.details-table + .section-title {
    margin-top: 0px !important;
}

.print-format p,
.print-format div,
.print-format table {
    margin-bottom: 0px !important;
}
.adjustment-table {
    border-collapse: collapse !important;
    border-spacing: 0 !important;
}

.adjustment-table tr {
    height: 18px !important;
}

.adjustment-table td {
    margin: 0 !important;
}

.adjustment-table th {
    margin: 0 !important;
}

html:
{# ============================================================
   COMPANY DETAILS
   ============================================================ #}

{% set company_doc = frappe.get_doc("Company", doc.company) %}

{# Find Company Address directly from Address Dynamic Link #}

{% set company_addresses = frappe.get_all(
    "Address",
    filters={
        "name": [
            "in",
            frappe.get_all(
                "Dynamic Link",
                filters={
                    "link_doctype": "Company",
                    "link_name": doc.company
                },
                pluck="parent"
            )
        ]
    },
    fields=[
        "name",
        "address_line1",
        "address_line2",
        "city",
        "state",
        "pincode",
        "country"
    ],
    limit=1
) %}

{% set company_address = None %}

{% if company_addresses %}
    {% set company_address = company_addresses[0] %}
{% endif %}


<div class="company-name">
    {{ company_doc.company_name }}
</div>


<div class="company-address">

    {% if company_address %}

        {% if company_address.address_line1 %}
            {{ company_address.address_line1 }}
        {% endif %}

        {% if company_address.address_line2 %}
            , {{ company_address.address_line2 }}
        {% endif %}

        {% if company_address.city %}
            , {{ company_address.city }}
        {% endif %}

        {% if company_address.state %}
            , {{ company_address.state }}
        {% endif %}

        {% if company_address.pincode %}
            - {{ company_address.pincode }}
        {% endif %}

        {% if company_address.country %}
            , {{ company_address.country }}
        {% endif %}

    {% endif %}

</div>


{# ============================================================
   PARTY DETAILS
   ============================================================ #}

<div class="party-section">

    <div class="party-left">

        <b>To,</b><br>


        {# ----------------------------------------------------
           Find Party Address
           Payment Entry Party = Supplier
           ---------------------------------------------------- #}

        {% set party_address_names = frappe.get_all(
            "Dynamic Link",
            filters={
                "link_doctype": doc.party_type,
                "link_name": doc.party
            },
            pluck="parent"
        ) %}


        {% set party_addresses = frappe.get_all(
            "Address",
            filters={
                "name": [
                    "in",
                    party_address_names
                ]
            },
            fields=[
                "name",
                "address_line1",
                "address_line2",
                "city",
                "state",
                "pincode",
                "country"
            ],
            limit=1
        ) %}


        {% set party_address = None %}

        {% if party_addresses %}
            {% set party_address = party_addresses[0] %}
        {% endif %}


        <b>{{ doc.party_name or doc.party }}</b><br>


        {# ----------------------------------------------------
           Party Address
           ---------------------------------------------------- #}

        {% if party_address %}

            {% if party_address.address_line1 %}
                {{ party_address.address_line1 }}
            {% endif %}

            {% if party_address.address_line2 %}
                , {{ party_address.address_line2 }}
            {% endif %}

            <br>

            {% if party_address.city %}
                {{ party_address.city }}
            {% endif %}

            {% if party_address.state %}
                , {{ party_address.state }}
            {% endif %}

            {% if party_address.pincode %}
                - {{ party_address.pincode }}
            {% endif %}

            {% if party_address.country %}
                , {{ party_address.country }}
            {% endif %}

        {% endif %}

    </div>


    <div class="party-right">

        <b>Date :</b>

        {{ frappe.utils.formatdate(
            doc.posting_date,
            "dd-mm-yyyy"
        ) }}

    </div>

</div>


<div class="clearfix"></div>

<div class="separator"></div>

<br>


{# ============================================================
   PAYMENT DETAILS
   ============================================================ #}

<table class="details-table">

<tr>
    <td><b>Bank Name :</b></td>
    <td>{{ doc.paid_from }}</td>
</tr>


<tr>
    <td><b>Cheque No :</b></td>
    <td>{{ doc.reference_no }}</td>
</tr>


<tr>
    <td><b>Cheque Date :</b></td>
    <td>
        {{ frappe.utils.formatdate(doc.reference_date) }}
    </td>
</tr>


<tr>
    <td><b>Cheque Amount :</b></td>
    <td>{{ doc.paid_amount }}</td>
</tr>


<tr>
    <td><b>Amount In Words :</b></td>
    <td>{{ doc.base_in_words }}</td>
</tr>


<tr>
    <td><b>Reference :</b></td>

    <td>
        {{ doc.name }}
        &nbsp;&nbsp;&nbsp;&nbsp;
        Dated:
        {{ frappe.utils.formatdate(doc.posting_date) }}
    </td>
</tr>


<tr>
    <td><b>Remarks :</b></td>
    <td></td>
</tr>

</table>


<br>
{# ============================================================
   CLEARING ADJUSTMENTS
   ============================================================ #}

<div class="section-title">
    Clearing Adjustments :
</div>

<br>

{% for ref in doc.references %}

    {% set pi = frappe.get_doc(
        "Purchase Invoice",
        ref.reference_name
    ) %}


    {# ========================================================
       GET TOTAL TDS DIRECTLY FROM PURCHASE INVOICE TAXES
       ======================================================== #}

    {% set tds_rows = frappe.db.sql("""
        SELECT
            SUM(tax_amount) AS total_tds
        FROM `tabPurchase Taxes and Charges`
        WHERE parent = %s
        AND parenttype = 'Purchase Invoice'
        AND is_tax_withholding_account = 1
    """, ref.reference_name, as_dict=1) %}


    {% set total_tds = 0 %}

    {% if tds_rows and tds_rows[0].total_tds %}
        {% set total_tds = frappe.utils.flt(tds_rows[0].total_tds) %}
    {% endif %}


    {# ========================================================
       FINAL DOC AMOUNT
       GRAND TOTAL + TDS
       ======================================================== #}

    {% set doc_amount =
        frappe.utils.flt(pi.grand_total) + total_tds
    %}


    {# ========================================================
       FINAL ADJUSTED AMOUNT
       ALLOCATED AMOUNT + TDS
       ======================================================== #}

    {% set adjusted_amount =
        frappe.utils.flt(ref.allocated_amount) + total_tds
    %}


    {# ========================================================
       PURCHASE INVOICE DETAILS
       ======================================================== #}

    {{ loop.index }}. Against {{ ref.reference_name }}
    Dated: {{ frappe.utils.formatdate(pi.posting_date) }}

    (Doc No: {{ pi.bill_no or "" }}
    Doc Dt: {{ frappe.utils.formatdate(pi.bill_date)
        if pi.bill_date else "" }}
    Doc Amt: Rs. {{ "%.3f"|format(doc_amount) }})

    Adjusted Amt: Rs. {{ "%.3f"|format(adjusted_amount) }}

    <br>


    {# ========================================================
       TDS
       ======================================================== #}

    {% if total_tds > 0 %}

        &nbsp;&nbsp;&nbsp;&nbsp;
        TDS: Rs. {{ "%.3f"|format(total_tds) }}

        <br>

    {% endif %}


    {# ========================================================
       DISCOUNT / JV
       ======================================================== #}

    {% set discount_rows = frappe.db.sql("""
        SELECT
            p.parent AS jv_name,
            j.posting_date AS jv_date,
            d.debit,
            d.credit

        FROM `tabJournal Entry Account` p

        INNER JOIN `tabJournal Entry` j
            ON j.name = p.parent

        INNER JOIN `tabJournal Entry Account` d
            ON d.parent = p.parent

        WHERE p.reference_type = 'Purchase Invoice'
        AND p.reference_name = %s
        AND p.party = %s
        AND j.docstatus = 1
        AND (d.party IS NULL OR d.party = '')

    """, (
        ref.reference_name,
        doc.party
    ), as_dict=1) %}


    {% for d in discount_rows %}

        &nbsp;&nbsp;&nbsp;&nbsp;

        Against {{ d.jv_name }}

        Dated: {{ frappe.utils.formatdate(d.jv_date) }}

        Discount Amt:
        Rs. {{ "%.3f"|format(
            frappe.utils.flt(d.debit or d.credit)
        ) }}

        <br>

    {% endfor %}


    <br>

{% endfor %}
